class ModelNew(torch.nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, predictions, targets):
        # Prepare inputs for kernel
        num_elements = predictions.numel()

        # Allocate output tensor
        output = torch.empty(1, dtype=torch.float16)

        # Call the TileLang kernel
        hinge_loss_kernel_tiled(
            predictions.data_ptr(),
            targets.data_ptr(), 
            output.data_ptr(),
